import {services,staff,localDay,minutes,clock,book,transition,empty,validate} from './engine.js';
const $=s=>document.querySelector(s),key='queueflow-demo-v1';let view='overview',filter='all',search='',date=localDay(),editId=null,pending=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=empty();try{const s=JSON.parse(localStorage.getItem(key));if(s?.version===1&&Array.isArray(s.entries)&&s.settings&&Array.isArray(s.settings.away)&&Array.isArray(s.settings.closedDates))state=s;}catch{}
const labels={booked:'Scheduled',waiting:'Waiting',serving:'In service',completed:'Completed',cancelled:'Cancelled',noshow:'No-show'};
const serviceFor=e=>services.find(s=>s.id===e.service)||services[0];
const initials=name=>name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function mutate(fn){if(!navigator.onLine){toast('You are offline. Reconnect before changing appointments.');return false;}try{const commit=()=>{let fresh=empty();const raw=localStorage.getItem(key);if(raw)fresh=JSON.parse(raw);const next=fn(fresh);localStorage.setItem(key,JSON.stringify(next));state=next;};if(navigator.locks)await navigator.locks.request(key,commit);else{toast('This browser cannot safely coordinate changes. Use an up-to-date browser.');return false;}render();return true;}catch(e){toast(e.message||'Could not save. Browser storage may be full or unavailable.');return false;}}
window.addEventListener('storage',e=>{if(e.key===key){try{state=e.newValue?JSON.parse(e.newValue):empty();render();}catch{toast('Stored data could not be loaded.');}}});
window.addEventListener('offline',()=>{toast('Connection lost. Changes are paused until you reconnect.');$('#save-status').textContent='Offline · Changes paused';});window.addEventListener('online',()=>{$('#save-status').textContent='Browser-local data · No reminders sent';toast('Back online.');});
const todayEntries=()=>state.entries.filter(e=>e.date===localDay());
const status=e=>`<span class="status ${esc(e.status)}">${esc(labels[e.status])}</span>`;
function actions(e){return `<div class="actions">${e.status==='booked'?`<button data-action="waiting" data-id="${e.id}">Check in</button><button data-edit="${e.id}">Edit</button>`:''}${e.status==='waiting'?`<button data-action="serving" data-id="${e.id}">Start →</button>`:''}${e.status==='serving'?`<button data-action="completed" data-id="${e.id}">Complete ✓</button>`:''}${['booked','waiting'].includes(e.status)?`<button data-action="cancelled" data-id="${e.id}" class="danger">Cancel</button><button data-action="noshow" data-id="${e.id}">No-show</button>`:''}</div>`;}
function stats(){const items=todayEntries(),wait=items.filter(e=>e.status==='waiting');return `<div class="stats"><div class="stat"><div class="stat-head"><span>Today’s appointments</span><span>▤</span></div><div class="stat-value">${items.filter(e=>e.status!=='cancelled').length}</div><small>${items.filter(e=>e.status==='booked').length} still scheduled today</small></div><div class="stat highlight"><div class="stat-head"><span>In the queue</span><span>☷</span></div><div class="stat-value">${wait.length.toString().padStart(2,'0')}</div><small>${state.settings.paused?'Check-in is paused':'Ready when you are'}</small></div><div class="stat"><div class="stat-head"><span>Completed today</span><span>✓</span></div><div class="stat-value">${items.filter(e=>e.status==='completed').length.toString().padStart(2,'0')}</div><small>A little more time well spent</small></div><div class="stat"><div class="stat-head"><span>Queued service time</span><span>◷</span></div><div class="stat-value">${wait.reduce((a,e)=>a+serviceFor(e).minutes,0)} <sub>min</sub></div><small>Total workload, not a wait promise</small></div></div>`;}
function appointments(compact=false){let entries=state.entries.filter(e=>e.date===date&&(filter==='all'||e.status===filter)&&`${e.name} ${e.phone} ${e.staff}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.time.localeCompare(b.time));const count=entries.length;if(compact)entries=entries.slice(0,6);return `<section class="panel"><div class="panel-title"><div><h2>${compact?'Today’s appointments':'Appointments'}</h2><p>A little organization. A smoother day.</p></div><button class="text-link" data-view="${compact?'appointments':'customer'}">${compact?'View all appointments':'Open booking page'} ↗</button></div><div class="filters"><input id="search" type="search" placeholder="Search customer or team…" aria-label="Search appointments" value="${esc(search)}"><input id="date-filter" type="date" aria-label="Appointment date" value="${date}"></div><div class="tabs">${[['all','All'],['booked','Scheduled'],['waiting','Waiting'],['completed','Completed']].map(([v,l])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${l}</button>`).join('')}<select id="other-status" aria-label="More status filters"><option value="all">More</option>${['serving','cancelled','noshow'].map(v=>`<option value="${v}" ${filter===v?'selected':''}>${labels[v]}</option>`).join('')}</select></div>${entries.length?`<div class="table-scroll"><table><thead><tr><th>CUSTOMER</th><th>TIME / SERVICE</th><th>TEAM</th><th>STATUS</th>${!compact?'<th>ACTIONS</th>':''}</tr></thead><tbody>${entries.map(e=>`<tr><td><div class="customer-cell"><span class="avatar">${esc(initials(e.name))}</span><div><b>${esc(e.name)}</b><small>${esc(e.phone)}</small></div></div></td><td><b>${e.time}</b><small>${serviceFor(e).name} · ${serviceFor(e).minutes} min</small></td><td>${esc(e.staff.split(' ')[0])}<small>${e.ticket?'Ticket #'+e.ticket:'By appointment'}</small></td><td>${status(e)}</td>${!compact?`<td>${actions(e)}</td>`:''}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>No appointments here yet.</strong>Book a little breathing room into the day.<p><button class="secondary" data-book>＋ Add an appointment</button></p></div>`}<div class="table-footer">Showing ${entries.length} of ${count} appointments · Device local time</div></section>`;}
function queue(){const items=todayEntries(),serving=items.filter(e=>e.status==='serving'),waiting=items.filter(e=>e.status==='waiting').sort((a,b)=>(a.ticket||0)-(b.ticket||0));return `<section class="panel queue-panel"><div class="panel-title"><div><h2>Live queue</h2><p>One person closer to a great day.</p></div><span class="live">● ${state.settings.paused?'PAUSED':'LOCAL'}</span></div>${serving.length?serving.map(e=>`<div class="serving-card"><div class="overline">NOW SERVING <span class="ticket">#${String(e.ticket).padStart(2,'0')}</span></div><h3>${esc(e.name)}</h3><p>${serviceFor(e).name} · with ${esc(e.staff.split(' ')[0])}</p>${actions(e)}</div>`).join(''):`<div class="serving-card"><div class="overline">READY FOR THE NEXT PERSON</div><h3>A moment to catch your breath.</h3><p>${waiting.length?'Start service for a waiting customer below.':'No customers are currently in service.'}</p></div>`}<div class="queue-label">UP NEXT <span>(${waiting.length})</span></div><div class="queue-list">${waiting.length?waiting.map(e=>`<div class="queue-row"><span class="queue-number">${String(e.ticket).padStart(2,'0')}</span><div><b>${esc(e.name)}</b><small>${serviceFor(e).name} · ${esc(e.staff.split(' ')[0])}</small></div>${actions(e)}</div>`).join(''):'<div class="empty">The queue is clear. You’re all caught up.</div>'}</div><div class="queue-bottom">◷ Queue order follows check-in. Each team member can serve one person at a time. Duration estimates can change.</div></section>`;}
function team(compact=false){if(compact)return `<section class="panel"><div class="panel-title"><h2>Your team today</h2><button class="text-link" data-view="team">Manage team ↗</button></div><div class="team-list">${staff.map(n=>`<div class="team-person"><span class="avatar">${initials(n)}</span><div><b>${n}</b><small>● ${state.settings.away.includes(n)?'Away':todayEntries().some(e=>e.staff===n&&e.status==='serving')?'In service':'Available'}</small></div></div>`).join('')}</div></section>`;return `<div class="settings-grid">${staff.map(n=>`<section class="panel settings-card"><span class="avatar">${initials(n)}</span><h3>${n}</h3><p>${state.settings.away.includes(n)?'Away — new bookings are blocked.':'Available for new appointments.'}<br>${state.entries.filter(e=>e.staff===n&&['booked','waiting','serving'].includes(e.status)).length} active appointments remain. Existing bookings are preserved when availability changes.</p><button class="secondary" data-away="${n}">${state.settings.away.includes(n)?'Mark available':'Mark away'}</button></section>`).join('')}</div>`;}
function settings(){return `<div class="settings-grid"><section class="panel settings-card"><h3>Queue controls</h3><p>Pause new check-ins while your team catches up. Existing customers can still be served.</p><button class="secondary" id="pause-queue">${state.settings.paused?'Resume check-in':'Pause check-in'}</button><label>Maximum active queue size<input id="capacity" type="number" min="1" max="100" value="${state.settings.capacity}"></label><button class="secondary" id="save-capacity">Save capacity</button></section><section class="panel settings-card"><h3>Business hours</h3><p>Monday–Saturday · 09:00–18:00<br>Lunch break · 13:00–14:00<br>Sunday · Closed<br>Bookings open 60 days ahead, in 15-minute increments.<br>Timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)} (device local; demo only).</p><label>Close a date<input type="date" id="closed-date"></label><button class="secondary" id="add-closure">Add closure</button><p>${state.settings.closedDates.map(d=>`${d} <button class="text-link" data-remove-closure="${d}">Reopen ×</button>`).join('<br>')||'No additional closures.'}</p><p>Closures prevent new bookings. Review and reschedule existing appointments separately.</p></section><section class="panel settings-card"><h3>Data & connection</h3><p>Demo data is stored on this browser only. No Firebase account, server, reminders, payments, or real customer access is active.</p><div class="actions"><button id="export-data">Export demo data</button><button id="reset-data" class="danger">Clear demo data</button><button id="firebase-info">Firebase setup</button></div></section><section class="panel settings-card"><h3>Try a busier day</h3><p>Load fictional appointments and a sample queue to explore staff workflows. Existing records are kept.</p><button id="sample-data" class="secondary">Load sample day</button><p>Demo roles share this browser’s data. Customer view is a preview, not an access boundary.</p></section></div>`;}
function customer(){return `<div class="pill-note">Customer view preview · All demo data is visible in this browser. Use fictional details only.</div><section class="customer-hero"><small>STUDIO & CO. / YOUR TIME MATTERS</small><h2>A little less waiting.<br>A little more living.</h2><p>Book a time that works for you. Check in up to 30 minutes before your appointment and follow the queue right here.</p><button class="primary" data-book>Find your next appointment ↗</button></section><div class="service-grid">${services.map(s=>`<section class="panel service-card"><small class="eyebrow">${s.minutes} MINUTES, JUST FOR YOU</small><h3>${s.name}</h3><p>PKR ${s.price.toLocaleString()} · Pay at the business</p><button class="primary" data-service="${s.id}">Choose service ↗</button></section>`).join('')}</div><div class="lower">${appointments(false)}${queue()}</div>`;}
function render(){const titles={overview:['A good day starts here.','A clear view of your appointments, your team, and who’s up next.'],appointments:['A place for every appointment.','Book, check in, reschedule, and keep the day moving.'],queue:['Less waiting. More flow.','Help the next person, one smooth handoff at a time.'],team:['Good people. Great days.','Keep availability clear and your team in sync.'],settings:['Make it work for you.','Your hours, queue, and demo workspace controls.'],customer:['Make a little time for yourself.','Welcome to Studio & Co. Choose your service and we’ll make room.']};$('#page-title').textContent=titles[view][0];$('#page-subtitle').textContent=titles[view][1];$('#crumb').textContent=view==='customer'?'Customer booking':view[0].toUpperCase()+view.slice(1);$('#today-label').textContent=new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();$('#nav-count').textContent=todayEntries().length;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));$('#content').innerHTML=view==='overview'?`${stats()}<div class="dashboard-grid">${appointments(true)}${queue()}</div><div class="lower">${team(true)}<aside class="tip"><small>A SMOOTHER DAY, BY DESIGN</small><h3>Give every customer their time.</h3><p>Keep your queue moving with a quick check-in and a clear next step. Small moments make a big difference.</p></aside></div>`:view==='appointments'?appointments():view==='queue'?`${stats()}${queue()}`:view==='team'?team():view==='settings'?settings():customer();}
function openBooking(id=null,service=null){editId=id;const f=$('#booking-form');f.reset();$('#form-error').textContent='';$('#service-select').innerHTML=services.map(s=>`<option value="${s.id}">${s.name}</option>`).join('');$('#staff-select').innerHTML=staff.map(n=>`<option>${n}</option>`).join('');f.elements.date.min=localDay();const max=new Date();max.setDate(max.getDate()+60);f.elements.date.max=localDay(max);f.elements.date.value=localDay();if(id){const e=state.entries.find(e=>e.id===id);for(const k of ['name','phone','service','staff','date'])f.elements[k].value=e[k];}if(service)f.elements.service.value=service;$('#modal-title').textContent=id?'Reschedule appointment':'New appointment';f.dataset.requestId=crypto.randomUUID();updateSlots();if(id)f.elements.time.value=state.entries.find(e=>e.id===id).time;$('#booking-dialog').showModal();}
function updateSlots(){const f=$('#booking-form'),s=services.find(s=>s.id===f.elements.service.value);$('#booking-summary').textContent=`${s.minutes} minutes · PKR ${s.price.toLocaleString()} · Pay at the business`;const prev=f.elements.time.value;let slots='';for(let m=540;m<1080;m+=15){const input={name:'Slot check',phone:'0000000000',service:s.id,staff:f.elements.staff.value,date:f.elements.date.value,time:clock(m)};try{validate(state,input,new Date(),editId);slots+=`<option value="${clock(m)}">${clock(m)}</option>`;}catch{}}$('#time-select').innerHTML=slots||'<option value="">No available slots</option>';if([...f.elements.time.options].some(o=>o.value===prev))f.elements.time.value=prev;f.querySelector('[type=submit]').disabled=!slots;}
$('#booking-form').addEventListener('change',e=>{if(['service','staff','date'].includes(e.target.name))updateSlots();});
$('#booking-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;$('#form-error').textContent='';const input=Object.fromEntries(new FormData(f));input.requestId=f.dataset.requestId;try{validate(state,input,new Date(),editId);const ok=await mutate(s=>book(s,input,new Date(),editId));if(ok){$('#booking-dialog').close();toast(editId?'Appointment rescheduled.':'Appointment booked. No reminders are sent in demo mode.');}}catch(err){$('#form-error').textContent=err.message;}finally{b.disabled=false;}});
function confirm(title,copy,fn){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;pending=fn;$('#confirm-dialog').showModal();}
$('#confirm-action').addEventListener('click',async()=>{const fn=pending;pending=null;$('#confirm-dialog').close();if(fn)await fn();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.close){$('#'+b.dataset.close).close();return;}
 if(b.dataset.view){view=b.dataset.view;search='';filter='all';date=localDay();$('.sidebar').classList.remove('open');render();return;}
 if(b.dataset.book!==undefined||b.id==='new-booking'){openBooking();return;}
 if(b.dataset.service){openBooking(null,b.dataset.service);return;}
 if(b.dataset.edit){openBooking(b.dataset.edit);return;}
 if(b.dataset.filter){filter=b.dataset.filter;render();return;}
 if(b.dataset.action){const run=async()=>{if(await mutate(s=>transition(s,b.dataset.id,b.dataset.action)))toast('Appointment updated.');};if(['cancelled','noshow'].includes(b.dataset.action))confirm(b.dataset.action==='cancelled'?'Cancel this appointment?':'Mark as a no-show?',b.dataset.action==='cancelled'?'This releases the slot. Cancelled appointments cannot be restored; create a new booking if needed.':'Only mark a no-show after the 15-minute grace period. This releases the slot.',run);else await run();return;}
 if(b.dataset.away){await mutate(s=>({...s,settings:{...s.settings,away:s.settings.away.includes(b.dataset.away)?s.settings.away.filter(n=>n!==b.dataset.away):[...s.settings.away,b.dataset.away]}}));return;}
 if(b.dataset.removeClosure){await mutate(s=>({...s,settings:{...s.settings,closedDates:s.settings.closedDates.filter(d=>d!==b.dataset.removeClosure)}}));return;}
 if(b.id==='customer-view'){view='customer';render();}
 if(b.id==='menu')$('.sidebar').classList.toggle('open');
 if(['connection-info','firebase-info'].includes(b.id))$('#info-dialog').showModal();
 if(b.id==='pause-queue')await mutate(s=>({...s,settings:{...s.settings,paused:!s.settings.paused}}));
 if(b.id==='save-capacity'){const cap=Number($('#capacity').value);if(!Number.isInteger(cap)||cap<1||cap>100){toast('Capacity must be a whole number from 1 to 100.');return;}if(await mutate(s=>({...s,settings:{...s.settings,capacity:cap}})))toast('Queue capacity saved. Existing customers remain in the queue.');}
 if(b.id==='add-closure'){const d=$('#closed-date').value;if(!d||d<localDay()){toast('Choose today or a future date.');return;}confirm('Close this date?',`New bookings for ${d} will be blocked. Review existing appointments and contact affected customers separately.`,()=>mutate(s=>({...s,settings:{...s.settings,closedDates:[...new Set([...s.settings.closedDates,d])]}})));}
 if(b.id==='reset-data')confirm('Clear all demo data?','This permanently deletes the appointments and settings stored by this demo in this browser.',()=>mutate(()=>empty()));
 if(b.id==='sample-data'){const saved=await mutate(s=>{const today=localDay(),names=['Jordan Lee','Amelia Carter','Noah Williams','Isabella Chen','Ethan Brooks','Mia Patel'],statuses=['serving','waiting','waiting','booked','completed','booked'];if(s.entries.some(e=>e.date===today))throw Error('Sample data requires an empty day to avoid conflicts with existing bookings.');const sample=names.map((name,i)=>({id:crypto.randomUUID(),name,phone:'+92 300 00000'+String(i).padStart(2,'0'),service:i===1?'followup':'consult',staff:staff[i%3],date:today,time:['09:00','09:30','10:00','10:30','11:00','11:30'][i],status:statuses[i],ticket:i<3?i+1:null,sample:true,createdAt:new Date().toISOString()}));return {...s,entries:[...s.entries,...sample]};});if(saved)toast('Fictional sample day loaded.');}
 if(b.id==='export-data'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='queueflow-demo-'+localDay()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.addEventListener('change',e=>{if(e.target.id==='date-filter'){date=e.target.value;render();}if(e.target.id==='other-status'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const cursor=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d&&e.clientX){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
render();
